const items = [
  {id:'tiktok', name:'TikTok @styloairpool', query:'https://www.tiktok.com/@styloairpool?lang=en'},
  {id:'instagram-airpoolstylo', name:'Instagram @airpoolstylo', query:'https://www.instagram.com/airpoolstylo/'},
  {id:'instagram-abangcolek', name:'Instagram @abangcolek', query:'https://www.instagram.com/abangcolek/'},
  {id:'instagram-liurleleh', name:'Instagram @liurlelehhouse', query:'https://www.instagram.com/liurlelehhouse/'},
  {id:'facebook', name:'Facebook Abangcolek/founder', query:'Facebook public identity for Abangcolek and founder'},
  {id:'lemon8', name:'Lemon8 @styloairpool', query:'https://www.lemon8-app.com/@styloairpool?region=my'},
  {id:'threads', name:'Threads @airpoolstylo', query:'Threads public identity for @airpoolstylo and Abangcolek'}
];
const schema = JSON.stringify({type:'object',properties:{id:{type:'string'},platform:{type:'string'},target:{type:'string'},urls:{type:'array',items:{type:'string'}},identity_status:{type:'string'},metrics:{type:'array',items:{type:'string'}},bio_or_positioning:{type:'string'},content_patterns:{type:'array',items:{type:'string'}},brand_relationship:{type:'string'},evidence:{type:'array',items:{type:'string'}},limitations:{type:'array',items:{type:'string'}},confidence:{type:'string'}},required:['id','platform','target','urls','identity_status','metrics','bio_or_positioning','content_patterns','brand_relationship','evidence','limitations','confidence']});
const mapped = await parallel('Audit tujuh saluran sosial founder', () => items.map(item => agent(
  'Audit exactly one public social-media target: '+item.name+'. Target URL or discovery hint: '+item.query+'. Use current public web sources where accessible; do not log in, bypass blocks, inspect private data, or invent ownership. Determine whether the account is official, historical, partner, personal, or unverified in relation to ABANGCOLEK founder. Record visible metrics only when directly observed, summarize bio/positioning and content patterns, list URLs and evidence, and state limitations. Return JSON matching the shared schema with id='+item.id+'.',
  {brief:'Audit '+item.name, schema, sandbox:'shared', effort_level:'lite'}
  )), {schema});
const successful = mapped.filter(r=>r.ok).map(r=>r.value);
const failures = mapped.map((r,i)=>r.ok?null:{target:items[i].name,code:r.error.code,message:r.error.message}).filter(Boolean);
const reducerSchema = JSON.stringify({type:'object',properties:{summary:{type:'string'},identity_map:{type:'array',items:{type:'object',properties:{platform:{type:'string'},account:{type:'string'},status:{type:'string'},confidence:{type:'string'},url:{type:'string'}},required:['platform','account','status','confidence','url']}},cross_platform_patterns:{type:'array',items:{type:'string'}},platform_recommendations:{type:'array',items:{type:'string'}},risks_and_unknowns:{type:'array',items:{type:'string'}},source_notes:{type:'array',items:{type:'string'}}},required:['summary','identity_map','cross_platform_patterns','platform_recommendations','risks_and_unknowns','source_notes']});
const reduced = await agent('Synthesize this cross-platform founder social audit into one concise, evidence-based report. Preserve distinctions between official, historical, partner, personal and unverified accounts. Do not upgrade weak evidence into fact. Include an identity map, shared content patterns, platform-specific recommendations for ABANGCOLEK-PLATFORM, risks/unknowns, and source notes. Results: '+JSON.stringify(successful), {brief:'Synthesize founder social audit', schema:reducerSchema, sandbox:'shared', effort_level:'standard'});
return {items:successful, failures, synthesis:reduced.ok?reduced.value:null};

